func testBancoToManyAddOpBanBancoCarteiras(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Banco
	var b, c, d, e BancoCarteiras

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, bancoDBTypes, false, strmangle.SetComplement(bancoPrimaryKeyColumns, bancoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*BancoCarteiras{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, bancoCarteirasDBTypes, false, strmangle.SetComplement(bancoCarteirasPrimaryKeyColumns, bancoCarteirasColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*BancoCarteiras{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddBanBancoCarteiras(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.BanID != first.BanID {
			t.Error("foreign key was wrong value", a.BanID, first.BanID)
		}
		if a.BanID != second.BanID {
			t.Error("foreign key was wrong value", a.BanID, second.BanID)
		}

		if first.R.Ban != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Ban != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.BanBancoCarteiras[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.BanBancoCarteiras[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.BanBancoCarteiras().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
